const ExampleComponent = () => {
  const hotTableRef = useRef(null);

  useEffect(() => {
    const hotInstance = hotTableRef.current?.hotInstance;

    if (!hotInstance) {
      return;
    }

    hotInstance.getPlugin('dialog').show();
  }, []);

  return (
    <HotTable
      ref={hotTableRef}
      data={data}
      width="100%"
      height={300}
      stretchH="all"
      contextMenu={true}
      rowHeaders={true}
      colHeaders={true}
      autoWrapRow={true}
      autoWrapCol={true}
      autoRowSize={true}
      dialog={{
        content: '<h2 id="example6-title">Title</h2><p id="example6-description">Description</p>',
        a11y: {
          role: 'alertdialog',
          ariaLabel: 'Title',
          ariaLabelledby: 'example6-title',
          ariaDescribedby: 'example6-description',
        },
        closable: true,
      }}
      // Required for the dialog's HTML content to be rendered safely
      sanitizer={sanitizeDialogContent}
      licenseKey="non-commercial-and-evaluation"
    >
      <HotColumn title="Model" type="text" data="model" width={150} headerClassName="htLeft" />
      <HotColumn
        title="Price"
        type="numeric"
        data="price"
        width={80}
        locale="en-US" numericFormat={{ style: 'currency', currency: 'USD', minimumFractionDigits: 2 }}
        className="htRight"
        headerClassName="htRight"
      />
      <HotColumn
        title="Date"
        type="intl-date"
        data="sellDate"
        width={131}
        locale="en-US" dateFormat={{ month: 'short', day: 'numeric', year: 'numeric' }}
        className="htRight"
        headerClassName="htRight"
      />
      <HotColumn
        title="Time"
        type="intl-time"
        data="sellTime"
        width={90}
        timeFormat={{ hour: '2-digit', minute: '2-digit', hour12: true }}
        className="htRight"
        headerClassName="htRight"
      />
      <HotColumn title="In stock" type="checkbox" data="inStock" className="htCenter" headerClassName="htCenter" />
    </HotTable>
  );
};

export default ExampleComponent;
